
const SEED={"staff":[],"entries":[],"expenses":[],"funds":[],"monthlySettings":{},"expenseCategories":["ค่าเช่า","ค่าน้ำ-ค่าไฟ","ค่าอุปกรณ์","ค่าของใช้","เครื่องดื่ม","อื่นๆ"],"shopName":""};
const COMMERCIAL_PROFILE=window.BarberStoreHost?.scope||'';const STORAGE='barber-storefront-shop-v1:'+COMMERCIAL_PROFILE;
const WEEK=['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์'];
const PAGES=[['learnForms','','แบบฟอร์มบันทึกข้อมูล'],['personal','🧾','สรุปส่วนบุคคล'],['dashboard','🏠','หน้าหลัก'],['summary','🧾','สรุปรายเดือน'],['annual','📆','สรุปข้อมูลประจำปี'],['entry','✂️','บันทึกงาน'],['daily','📅','รายวัน'],['monthly','📊','รายเดือน'],['goals','🎯','เป้าหมาย'],['income','💵','รายรับ'],['expenses','💸','รายจ่าย'],['analytics','📈','วิเคราะห์'],['history','🗂️','ประวัติ'],['staff','👥','จัดการช่างและร้าน'],['backup','💾','สำรองข้อมูล']];
const MENU_ORDER_KEY='barberCommercialV1MenuOrder';
const STAFF_AVATARS=['😎','🧑‍🎤','🥷','🧑‍🚀','🤠','🦸','🧑‍🔧','🕶️'];
let menuReorderMode=false;
function staffAvatar(i,name=''){const src=window.BarberStaff?.photo(name);return src?`<img class="staff-portrait" src="${esc(src)}" alt="รูป ${esc(name)}">`:STAFF_AVATARS[i%STAFF_AVATARS.length]}
function orderedPages(){let saved=[];try{saved=JSON.parse(WorkspaceStorage.getItem(MENU_ORDER_KEY)||'[]')}catch(e){}const map=Object.fromEntries(PAGES.map(x=>[x[0],x])),valid=Array.isArray(saved)?saved.filter(k=>map[k]):[],rest=PAGES.map(x=>x[0]).filter(k=>!valid.includes(k));return [...valid,...rest].map(k=>map[k])}
function persistMenuOrder(keys){WorkspaceStorage.setItem(MENU_ORDER_KEY,JSON.stringify(keys))}
function moveMenu(p,delta,e){e?.stopPropagation();const keys=orderedPages().map(x=>x[0]),i=keys.indexOf(p),j=i+delta;if(i<0||j<0||j>=keys.length)return;[keys[i],keys[j]]=[keys[j],keys[i]];persistMenuOrder(keys);renderNav()}
function toggleMenuReorder(){menuReorderMode=!menuReorderMode;renderNav()}
function resetMenuOrder(){WorkspaceStorage.removeItem(MENU_ORDER_KEY);renderNav();toast('คืนลำดับเมนูเริ่มต้นแล้ว')}
function menuNavigate(p,e){if(menuReorderMode){e?.preventDefault();return}go(p)}
function menuDragStart(e,p){if(!menuReorderMode){e.preventDefault();return}e.dataTransfer.setData('text/plain',p);e.dataTransfer.effectAllowed='move';e.currentTarget.classList.add('dragging')}
function menuDragOver(e){if(!menuReorderMode)return;e.preventDefault();e.dataTransfer.dropEffect='move';e.currentTarget.classList.add('drag-over')}
function menuDragLeave(e){e.currentTarget.classList.remove('drag-over')}
function menuDragEnd(e){document.querySelectorAll('.nav-row').forEach(x=>x.classList.remove('dragging','drag-over'))}
function menuDrop(e,target){if(!menuReorderMode)return;e.preventDefault();const from=e.dataTransfer.getData('text/plain');document.querySelectorAll('.nav-row').forEach(x=>x.classList.remove('dragging','drag-over'));if(!from||from===target)return;const keys=orderedPages().map(x=>x[0]),a=keys.indexOf(from),b=keys.indexOf(target);if(a<0||b<0)return;keys.splice(a,1);keys.splice(b,0,from);persistMenuOrder(keys);renderNav()}
let state=loadState(); let page='dashboard'; let filters={};
function clone(x){return JSON.parse(JSON.stringify(x))}
function upgrade(d){
 d=d&&typeof d==='object'?d:{}; d.staff=Array.isArray(d.staff)?d.staff:[]; d.entries=Array.isArray(d.entries)?d.entries:[]; d.expenses=Array.isArray(d.expenses)?d.expenses:[]; d.funds=Array.isArray(d.funds)?d.funds:[]; d.monthlySettings=d.monthlySettings||{}; d.expenseCategories=Array.isArray(d.expenseCategories)?d.expenseCategories:['ค่าเช่า','ค่าน้ำ-ค่าไฟ','ค่าอุปกรณ์','ค่าของใช้','เครื่องดื่ม','อื่นๆ'];
 d.shopName=typeof d.shopName==='string'?d.shopName:''; d.entries.forEach(x=>{if(x.notes==null)x.notes=''; if(!x.weekday&&x.date)x.weekday=weekday(x.date)}); d.expenses.forEach(x=>{if(!x.category)x.category='ยังไม่จัดหมวด'}); return d;
}
function loadState(){try{const s=WorkspaceStorage.getItem(STORAGE);return upgrade(s?JSON.parse(s):clone(SEED))}catch(e){return upgrade(clone(SEED))}}
function save(msg='บันทึกแล้ว'){WorkspaceStorage.setItem(STORAGE,JSON.stringify(state));toast(msg);render()}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function n(v){return Number(v)||0} function money(v){return '฿'+n(v).toLocaleString('th-TH',{maximumFractionDigits:2})} function num(v){return n(v).toLocaleString('th-TH')}
function isoToday(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function currentMonth(){return isoToday().slice(0,7)} function weekday(s){const [y,m,d]=s.split('-').map(Number);return WEEK[new Date(y,m-1,d).getDay()]}
function thDate(s,long=false){if(!s)return '';const [y,m,d]=s.split('-').map(Number);return new Intl.DateTimeFormat('th-TH',{day:'numeric',month:long?'long':'short',year:long?'numeric':undefined}).format(new Date(y,m-1,d))}
function monthLabel(m){const [y,mo]=m.split('-').map(Number);return new Intl.DateTimeFormat('th-TH',{month:'long',year:'numeric'}).format(new Date(y,mo-1,1))}
function id(){return 'id_'+Math.random().toString(36).slice(2,10)}
function sum(a,f=x=>x){return a.reduce((s,x)=>s+n(f(x)),0)}
function byMonth(a,m){return a.filter(x=>x.date?.startsWith(m))} function byDate(a,d){return a.filter(x=>x.date===d)}
function receiptSum(m){return sum(byMonth(state.funds,m),x=>x.amount)}
function expenseSum(m){return sum(byMonth(state.expenses,m),x=>x.amount)}
function allFinanceMonths(){return [...new Set([...state.funds.map(x=>x.date?.slice(0,7)),...state.expenses.map(x=>x.date?.slice(0,7)),...Object.keys(state.monthlySettings||{})].filter(Boolean))].sort()}
function balanceBaseMonth(){const configured=Object.keys(state.monthlySettings||{}).filter(m=>state.monthlySettings[m]&&state.monthlySettings[m].carryOver!=null).sort(),nonZero=configured.filter(m=>n(state.monthlySettings[m]?.carryOver)!==0);return nonZero[0]||configured[0]||allFinanceMonths()[0]||currentMonth()}
function nextMonth(m){let [y,mo]=m.split('-').map(Number);mo++;if(mo===13){mo=1;y++}return `${y}-${String(mo).padStart(2,'0')}`}
function openingBalance(m){const base=balanceBaseMonth();if(m<=base)return n(state.monthlySettings[m]?.carryOver);let cur=base,bal=n(state.monthlySettings[base]?.carryOver);let guard=0;while(cur<m&&guard++<240){bal=bal+receiptSum(cur)-expenseSum(cur);cur=nextMonth(cur)}return bal}
function centralBalance(m){return openingBalance(m)+receiptSum(m)-expenseSum(m)}
function yearOptions(selected){const cy=Number(isoToday().slice(0,4)),dataYears=[...state.entries,...state.funds,...state.expenses].map(x=>Number(x.date?.slice(0,4))).filter(Number.isFinite),oldest=Math.min(cy-10,...dataYears),ys=[];for(let y=cy;y>=oldest;y--)ys.push(String(y));if(selected&&!ys.includes(String(selected)))ys.push(String(selected));return ys.sort((a,b)=>Number(b)-Number(a)).map(y=>`<option value=\"${y}\" ${String(y)===String(selected)?'selected':''}>${Number(y)+543}</option>`).join('')}
function monthCutoffDay(m){const [y,mo]=m.split('-').map(Number),last=new Date(y,mo,0).getDate(),today=isoToday();if(m<today.slice(0,7))return last;if(m>today.slice(0,7))return 0;const td=Number(today.slice(8)),hasToday=state.entries.some(x=>x.date===today);return Math.max(0,Math.min(last,hasToday?td:td-1))}
function weekdayOccurrenceCounts(m){const [y,mo]=m.split('-').map(Number),cut=monthCutoffDay(m),o=Object.fromEntries(WEEK.map(w=>[w,0]));for(let d=1;d<=cut;d++)o[WEEK[new Date(y,mo-1,d).getDay()]]++;return o}
function chartMonthsForYear(y){const cy=Number(isoToday().slice(0,4)),yy=Number(y);if(yy<cy)return 12;if(yy>cy)return 0;return Number(isoToday().slice(5,7))}
function staffNames(){return state.staff.map(x=>x.name)}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),1800)}
function toggleSide(){document.getElementById('side').classList.toggle('open')}
const THEME_KEY='barberCommercialV1Theme';
function loadTheme(){const t=WorkspaceStorage.getItem(THEME_KEY)||'light';document.body.dataset.theme=t;updateThemeUI()}
function toggleTheme(){const t=document.body.dataset.theme==='dark'?'light':'dark';document.body.dataset.theme=t;WorkspaceStorage.setItem(THEME_KEY,t);updateThemeUI();toast(t==='dark'?'เปลี่ยนเป็นโหมดมืดแล้ว':'เปลี่ยนเป็นโหมดสว่างแล้ว')}
function updateThemeUI(){const dark=document.body.dataset.theme!=='light';const b=document.getElementById('themeToggle');if(b)b.textContent=dark?'☀️ โหมดสว่าง':'🌙 โหมดมืด';const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',dark?'#15111e':'#7b61ff')}
function go(p){page=p;document.getElementById('side').classList.remove('open');render()}
function renderNav(){const nav=document.getElementById('nav'),menu=orderedPages();nav.innerHTML=menu.map(([p,i,l])=>`<div class="nav-row ${menuReorderMode?'reorder-on':''}" data-page="${p}" draggable="${menuReorderMode?'true':'false'}" data-csp-dragstart="menu" data-csp-dragover="menu" data-csp-dragleave="menu" data-csp-dragend="menu" data-csp-drop="menu" data-csp-arg="${esc(p)}"><button data-page="${p}" class="nav-main ${page===p?'active':''}" data-csp-click="menu-navigate" data-csp-arg="${esc(p)}"><span class="nav-icon">${i}</span><span class="nav-text">${l}</span></button>${menuReorderMode?`<div class="menu-order-controls"><button title="เลื่อนขึ้น" data-csp-click="menu-up" data-csp-arg="${esc(p)}">↑</button><button title="เลื่อนลง" data-csp-click="menu-down" data-csp-arg="${esc(p)}">↓</button></div>`:''}</div>`).join('')+`<div class="menu-reorder-panel"><button class="menu-reorder-toggle ${menuReorderMode?'active':''}" data-csp-click="menu-reorder">${menuReorderMode?'✓ เสร็จสิ้นการจัดลำดับ':'⇅ จัดลำดับเมนู'}</button>${menuReorderMode?'<button class="menu-reset-btn" data-csp-click="menu-reset">↺ คืนลำดับเริ่มต้น</button><div class="menu-reorder-help">ลากเมนูขึ้น–ลง หรือกด ↑ ↓ • โปรแกรมจะจำลำดับนี้ไว้</div>':''}</div>`;const bn=document.getElementById('bottomnav');bn.classList.remove('hidden');bn.innerHTML=[['dashboard','🏠','หน้าแรก'],['entry','✂️','บันทึก'],['income','💵','รายรับ'],['expenses','💸','รายจ่าย'],['summary','🧾','สรุป']].map(([p,i,l])=>`<button data-page="${p}" class="${page===p?'active':''}" data-csp-click="go" data-csp-arg="${esc(p)}"><b class="bn-icon">${i}</b>${l}</button>`).join('')}
function render(){renderNav();updateThemeUI();document.getElementById('todayPill').textContent=weekday(isoToday())+' '+thDate(isoToday());document.getElementById('pageTitle').textContent=PAGES.find(x=>x[0]===page)?.[2]||'';const shopTop=document.getElementById('shopNameTop');if(shopTop)shopTop.textContent=(state.shopName||'ยังไม่ได้ตั้งชื่อร้าน'); const fn={learnForms:()=>"",personal:window.personalReportPage,dashboard:dashboardPage,summary:monthlySummaryPage,annual:annualSummaryPage,entry:entryPage,daily:dailyPage,monthly:monthlyPage,goals:goalsPage,income:incomePage,expenses:expensesPage,funds:fundsPage,analytics:analyticsPage,history:historyPage,staff:staffPage,backup:backupPage}[page]; document.getElementById('content').innerHTML=fn(); bindPage()}
function bindPage(){if(page==='backup')setTimeout(updateIDBBackupStatus,0);if(page==='daily'){document.getElementById('dailyDate')?.addEventListener('change',()=>{filters.daily=document.getElementById('dailyDate').value;render()})} if(page==='summary'){document.getElementById('summaryMonth')?.addEventListener('change',()=>{filters.summaryMonth=document.getElementById('summaryMonth').value;render()})} if(page==='annual'){document.getElementById('annualYear')?.addEventListener('change',()=>{filters.annualYear=document.getElementById('annualYear').value;render()})} if(page==='monthly'){document.getElementById('monthPick')?.addEventListener('change',()=>{filters.month=document.getElementById('monthPick').value;render()})} if(page==='goals'){document.getElementById('goalMonth')?.addEventListener('change',()=>{filters.goalMonth=document.getElementById('goalMonth').value;render()})} if(page==='analytics'){document.getElementById('anaMonth')?.addEventListener('change',()=>{filters.anaMonth=document.getElementById('anaMonth').value;render()});document.getElementById('anaYear')?.addEventListener('change',()=>{filters.anaYear=document.getElementById('anaYear').value;render()})} }
function dashboardPage(){const today=isoToday(),m=currentMonth(),te=byDate(state.entries,today),me=byMonth(state.entries,m),mx=byMonth(state.expenses,m),tin=sum(te,x=>x.amount),th=sum(te,x=>x.heads),mi=sum(me,x=>x.amount),mh=sum(me,x=>x.heads),openDays=new Set(me.map(x=>x.date).filter(Boolean)).size,ex=sum(mx,x=>x.amount),rin=receiptSum(m),cb=centralBalance(m),carry=openingBalance(m),prev=prevMonth(m),pme=byMonth(state.entries,prev),pmi=sum(pme,x=>x.amount),pmh=sum(pme,x=>x.heads);const change=(v,p)=>p?((v-p)/p*100):0;const incChange=change(mi,pmi),headChange=change(mh,pmh);return `
<div class="hero-card">
 <div class="hero-header"><div><div class="hero-kicker">✂ BARBER MANAGER</div><div class="hero-title">ภาพรวมร้าน • ${monthLabel(m)}</div><div class="hero-meta">สรุปภาพรวมรายได้ ลูกค้า รายรับ รายจ่าย และกองกลางในหน้าหลักแบบอ่านง่ายขึ้น • ข้อมูลใหม่จะยังถูกเก็บในเบราว์เซอร์เครื่องนี้เช่นเดิม</div></div><div class="hero-badges"><span class="hero-chip">👥 ${num(mh)} คน</span><span class="hero-chip">📅 เปิดร้าน ${num(openDays)} วัน</span></div></div>
 <div class="hero-stat-grid">
  <div class="hero-stat"><span>รายได้รวมร้าน</span><b>${money(mi)}</b><small class="${incChange>=0?'good':'bad'}">${pmi?`${incChange>=0?'▲':'▼'} ${Math.abs(incChange).toFixed(1)}% จากเดือนก่อน`:'ยังไม่มีข้อมูลเดือนก่อน'}</small></div>
  <div class="hero-stat"><span>ลูกค้าเดือนนี้</span><b>${num(mh)} คน</b><small class="${headChange>=0?'good':'bad'}">${pmh?`${headChange>=0?'▲':'▼'} ${Math.abs(headChange).toFixed(1)}% จากเดือนก่อน`:'ยังไม่มีข้อมูลเดือนก่อน'}</small></div>
  <div class="hero-stat"><span>รายรับ − รายจ่าย</span><b>${money(rin-ex)}</b><small>รายรับ ${money(rin)} • รายจ่าย <span class="expense-number">${money(ex)}</span></small></div>
  <div class="hero-stat"><span>กองกลางคงเหลือ</span><b class="balance-number">${money(cb)}</b><small>ยกมา <span class="balance-number">${money(carry)}</span></small></div>
 </div>
</div>
<div class="notice">ข้อมูลเดิมถูกโหลดไว้แล้ว • ${num(state.entries.length)} รายการงาน • ${num(state.expenses.length)} รายจ่าย • ${num(state.funds.length)} รายรับ • พร้อมใช้งานแบบ Offline</div>
<div class="grid kpis">
 ${kpi('รายได้รวมร้าน',money(mi),monthLabel(m))}
 ${kpi('จำนวนวันเปิดร้าน',num(openDays)+' วัน','นับวันที่มีช่างทำงานอย่างน้อย 1 คน')}
 ${kpi('รายรับเดือนนี้',money(rin),`${num(byMonth(state.funds,m).length)} รายการ`)}
 ${kpi('รายจ่ายเดือนนี้',money(ex),`${num(mx.length)} รายการ`)}
 ${kpi('กองกลางคงเหลือยกมา',money(carry),`ยอดคงเหลือจาก ${monthLabel(prev)}`)}
 ${kpi('กองกลางคงเหลือ',money(cb),`ยกมา ${money(carry)}`)}
</div><br>
<div class="grid two"><div class="card"><div class="section-title"><h2>รายงานยอด 7 วันล่าสุด</h2><span class="muted">ยอดเงิน + ลูกค้า</span></div>${bars7(today)}</div><div class="card"><div class="section-title"><h2>ผลงานช่างเดือนนี้</h2><button class="btn small" data-csp-click="go" data-csp-arg="monthly">ดูรายงาน</button></div>${staffPerformance(m)}</div></div><br>
<div class="grid three"><div class="card">${goalMini(m)}</div><div class="card"><div class="section-title"><h3>รายการงานล่าสุด</h3></div>${recentEntries(5)}</div><div class="card"><div class="section-title"><h3>รายจ่ายล่าสุด</h3></div>${recentExpenses(5)}</div></div>`}
function kpi(l,v,s){const cls=/คงเหลือ/.test(l)?' balance-number':(/รายจ่าย/.test(l)&&!/ผลต่าง/.test(l)?' expense-number':'');return `<div class="card kpi"><div class="label">${l}</div><div class="num${cls}">${v}</div><div class="sub">${s}</div></div>`}
function bars7(end){const [y,m,d]=end.split('-').map(Number),arr=[];for(let i=6;i>=0;i--){const z=new Date(y,m-1,d-i),s=[z.getFullYear(),String(z.getMonth()+1).padStart(2,'0'),String(z.getDate()).padStart(2,'0')].join('-'),rows=byDate(state.entries,s);arr.push([s,sum(rows,x=>x.amount),sum(rows,x=>x.heads)])}const mx=Math.max(...arr.map(x=>x[1]),1);return `<div class="barlist seven-bars">${arr.map(([d,a,h])=>`<div class="barcol interactive-bar" tabindex="0" data-csp-click="toggle-tip" data-csp-blur="close-tip" title="${thDate(d)} • ${money(a)} • ${num(h)} คน"><div class="bar-tip"><b>${money(a)}</b><span>👥 ${num(h)} คน</span></div><div class="bar" style="height:${Math.max(3,a/mx*140)}px"></div><small>${d.slice(8)}</small></div>`).join('')}</div><div class="muted" style="font-size:12px;margin-top:8px">แตะ/ชี้แท่งเพื่อดู <b>ยอดเงินและจำนวนลูกค้า</b> ของวันนั้นพร้อมกัน</div>`}
function staffPerformance(m){const rows=staffNames().map(s=>{const a=byMonth(state.entries,m).filter(x=>x.staff===s),days=window.BarberOps?BarberOps.workingDays(s,m):new Set(a.map(x=>x.date).filter(Boolean)).size;return [s,sum(a,x=>x.amount),sum(a,x=>x.heads),days]}).sort((a,b)=>b[1]-a[1]);const mx=Math.max(...rows.map(x=>x[1]),1);return rows.map(([s,a,h,days])=>`<div class="staff-row"><b>${esc(s)}</b><div><div class="progress"><i style="width:${a/mx*100}%"></i></div><small class="muted">${num(h)} คน • ${num(days)} วันทำงาน • ${h?money(a/h)+'/คน':'—'}</small></div><b>${money(a)}</b></div>`).join('')||'<div class="empty">ไม่มีข้อมูล</div>'}
function goalMini(m){const g=state.monthlySettings[m]?.goals?.total||{},e=byMonth(state.entries,m),a=sum(e,x=>x.amount),h=sum(e,x=>x.heads),pa=n(g.amount)?Math.min(100,a/n(g.amount)*100):0,ph=n(g.heads)?Math.min(100,h/n(g.heads)*100):0;return `<div class="section-title"><h3>🎯 เป้าหมายเดือนนี้</h3><button class="btn small" data-csp-click="go" data-csp-arg="goals">ตั้งค่า</button></div><div class="split"><span>รายได้</span><b>${money(a)} / ${money(g.amount)}</b></div><div class="progress"><i style="width:${pa}%"></i></div><br><div class="split"><span>ลูกค้า</span><b>${num(h)} / ${num(g.heads)} คน</b></div><div class="progress"><i style="width:${ph}%"></i></div>`}
function recentEntries(k){return state.entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,k).map(x=>`<div class="statline"><span>${esc(x.staff)} <small class="muted">${thDate(x.date)}</small></span><span class="recent-entry-right"><b>${money(x.amount)}</b><small class="recent-heads">👥 ${num(x.heads)} คน</small></span></div>`).join('')}
function recentExpenses(k){return state.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,k).map(x=>`<div class="statline"><span>${esc(x.desc)} <small class="muted">${thDate(x.date)}</small></span><b class="expense-number">${money(x.amount)}</b></div>`).join('')}
function byYear(arr,y){return arr.filter(x=>x.date?.startsWith(String(y)+'-'))}
function annualSummaryPage(){
 const y=String(filters.annualYear||isoToday().slice(0,4)),entries=byYear(state.entries,y),income=byYear(state.funds,y),expenses=byYear(state.expenses,y);
 const staff=staffNames().map((s,i)=>{const rows=entries.filter(x=>x.staff===s),days=window.BarberOps?BarberOps.workingDays(s,y):new Set(rows.map(x=>x.date).filter(Boolean)).size;return {name:s,amount:sum(rows,x=>x.amount),heads:sum(rows,x=>x.heads),days,idx:i}});
 const totalAmount=sum(entries,x=>x.amount),totalHeads=sum(entries,x=>x.heads),incomeTotal=sum(income,x=>x.amount),expenseTotal=sum(expenses,x=>x.amount),hasData=entries.length||income.length||expenses.length;
 return `<div class="annual-toolbar"><div class="field"><label>เลือกปีข้อมูล</label><select id="annualYear">${yearOptions(y)}</select></div><span class="year-badge">📆 ปี ${Number(y)+543}</span></div>
 <div class="annual-cover"><div class="eyebrow">ANNUAL DATA SUMMARY</div><h2>สรุปข้อมูลประจำปี • ${Number(y)+543}</h2><p>รวมข้อมูลยอดงานช่าง จำนวนลูกค้า รายรับ และรายจ่ายที่บันทึกไว้ในระบบสำหรับปีที่เลือก</p>
 <div class="annual-kpis"><div class="annual-kpi"><span>ยอดเงินงานช่างรวมทั้งปี</span><b>${money(totalAmount)}</b><small class="muted">รวมช่างทั้งหมด</small></div><div class="annual-kpi"><span>จำนวนลูกค้ารวมทั้งปี</span><b>${num(totalHeads)} คน</b><small class="muted">รวมช่างทั้งหมด</small></div><div class="annual-kpi"><span>รายรับรวมทั้งปี</span><b class="good">${money(incomeTotal)}</b><small class="muted">${num(income.length)} รายการ</small></div><div class="annual-kpi"><span>รายจ่ายรวมทั้งปี</span><b class="expense-number">${money(expenseTotal)}</b><small class="muted">${num(expenses.length)} รายการ</small></div></div></div><br>
 ${hasData?`<div class="card"><div class="section-title"><h2>สรุปช่างรายบุคคล</h2><span class="muted">ยอดเงิน + จำนวนลูกค้า + วันทำงานทั้งปี</span></div><div class="annual-staff-grid">${staff.map((s,i)=>`<div class="annual-staff-card"><div class="annual-staff-head"><div class="avatar av${i%8}">${staffAvatar(i,s.name)}</div><div><h3>${esc(s.name)}</h3><small class="muted">สรุปปี ${Number(y)+543}</small></div></div><div class="annual-staff-pair"><span>จำนวนลูกค้าทั้งปี</span><b>${num(s.heads)} คน</b></div><div class="annual-staff-pair"><span>ยอดเงินทั้งปี</span><b>${money(s.amount)}</b></div><div class="annual-staff-pair"><span>เฉลี่ย/คน</span><b>${s.heads?money(s.amount/s.heads):'—'}</b></div><div class="annual-staff-pair"><span>วันทำงานทั้งปี</span><b>${num(s.days)} วัน</b></div></div>`).join('')}</div></div><br>
 <div class="grid two"><div class="card"><div class="section-title"><h2>รวมช่างทั้งหมด</h2><span class="muted">${num(staff.length)} ช่าง</span></div><div class="annual-ledger-total">${money(totalAmount)}</div><div class="statline"><span>จำนวนลูกค้ารวม</span><b>${num(totalHeads)} คน</b></div><div class="statline"><span>ยอดเงินงานช่างรวม</span><b>${money(totalAmount)}</b></div><div class="statline"><span>เฉลี่ยต่อคน</span><b>${totalHeads?money(totalAmount/totalHeads):'—'}</b></div></div>
 <div class="card"><div class="section-title"><h2>รายรับ–รายจ่ายรวมทั้งปี</h2><span class="muted">ปี ${Number(y)+543}</span></div><div class="statline"><span>💵 รายรับรวม</span><b class="good">${money(incomeTotal)}</b></div><div class="statline"><span>💸 รายจ่ายรวม</span><b class="expense-number">${money(expenseTotal)}</b></div><div class="statline"><span>ผลต่างรายรับ − รายจ่าย</span><b class="${incomeTotal-expenseTotal<0?'bad':'good'}">${money(incomeTotal-expenseTotal)}</b></div><div class="tax-note">หมายเหตุ: หน้านี้เป็นการสรุปตัวเลขตามข้อมูลที่บันทึกไว้ใน Barber Manager เพื่อช่วยรวบรวมเอกสารประจำปี ไม่ใช่การคำนวณภาษีหรือการรับรองยอดทางภาษีโดยอัตโนมัติ</div></div></div>`:'<div class="card"><div class="empty">ยังไม่มีข้อมูลในปีที่เลือก</div></div>'}`
}
function monthlySummaryPage(){const m=filters.summaryMonth||currentMonth(),prev=prevMonth(m),e=byMonth(state.entries,m),pe=byMonth(state.entries,prev),h=sum(e,x=>x.heads),ph=sum(pe,x=>x.heads),a=sum(e,x=>x.amount),inc=byMonth(state.funds,m).slice().sort((x,y)=>x.date.localeCompare(y.date)),exp=byMonth(state.expenses,m).slice().sort((x,y)=>x.date.localeCompare(y.date)),incTotal=sum(inc,x=>x.amount),expTotal=sum(exp,x=>x.amount),bal=centralBalance(m),pct=ph?((h-ph)/ph*100):0,dir=pct>0?'up':pct<0?'down':'flat',arrow=pct>0?'⬆':pct<0?'⬇':'➡',staff=staffNames().map(s=>{const r=e.filter(x=>x.staff===s),days=window.BarberOps?BarberOps.workingDays(s,m):new Set(r.map(x=>x.date).filter(Boolean)).size;return {name:s,amount:sum(r,x=>x.amount),heads:sum(r,x=>x.heads),days}});return `<div class="summary-toolbar"><div class="field"><label>เดือนสรุป</label><select id="summaryMonth">${monthOptions(m)}</select></div><div><button class="btn primary save-jpg" data-csp-click="monthly-jpg" data-csp-arg="${esc(m)}">🖼️ Save เป็นภาพ JPG</button><div class="jpg-note">เหมาะสำหรับส่งใน LINE / กลุ่มสมาชิก / เก็บเป็นรายงาน</div></div></div><div class="card share-summary" id="monthlyShareSummary"><div class="summary-cover"><div class="eyebrow">MONTHLY MEMBER SUMMARY</div><h2>สรุปรายเดือน • ${monthLabel(m)}</h2><div class="summary-sub">รายงานข้อมูลสำคัญสำหรับสมาชิก • เปรียบเทียบกับ ${monthLabel(prev)}</div></div><div class="summary-body"><div class="summary-kpis"><div class="summary-kpi"><span>ลูกค้ารวมเดือนนี้</span><b>${num(h)} คน</b><div class="summary-change ${dir}">${arrow} ${ph?Math.abs(pct).toFixed(1)+'%':'—'} ${pct>0?'เพิ่มขึ้น':pct<0?'ลดลง':'เท่าเดิม'}</div></div><div class="summary-kpi"><span>ยอดเงินรวมทั้งหมด</span><b>${money(a)}</b><small class="muted">จากช่างทั้งหมด ${num(staff.length)} ราย</small></div><div class="summary-kpi"><span>กองกลางคงเหลือ</span><b class="balance-number">${money(bal)}</b><small class="muted">รายรับ ${money(incTotal)} − รายจ่าย <span class="expense-number">${money(expTotal)}</span></small></div></div><div class="summary-divider"></div><div class="section-title"><h2>สรุปช่างรายบุคคล</h2><span class="muted">ลูกค้า + ยอดเงิน + วันทำงาน</span></div><div class="member-staff-grid">${staff.map((s,i)=>`<div class="member-staff-card"><div class="avatar av${i%8}">${staffAvatar(i,s.name)}</div><h3>${esc(s.name)}</h3><div class="pair"><span>ลูกค้า</span><b>${num(s.heads)} คน</b></div><div class="pair"><span>ยอดเงิน</span><b>${money(s.amount)}</b></div><div class="pair"><span>จำนวนเฉลี่ย/วัน</span><b>${s.days?(s.heads/s.days).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+' คน/วัน':'—'}</b></div><div class="pair"><span>วันทำงาน</span><b>${num(s.days)} วัน</b></div></div>`).join('')}</div><div class="summary-divider"></div><div class="summary-ledgers"><div class="summary-ledger"><div class="section-title"><h3>💵 รายรับ</h3><b class="good">${money(incTotal)}</b></div>${summaryIncomeRows(inc)}</div><div class="summary-ledger"><div class="section-title"><h3>💸 รายจ่าย</h3><b class="expense-number">${money(expTotal)}</b></div>${summaryExpenseRows(exp)}</div></div></div></div>`}
function summaryIncomeRows(a){return a.length?a.map(x=>`<div class="statline"><span>${thDate(x.date)} • ${esc(x.desc)}</span><b class="good">＋${money(Math.abs(n(x.amount)))}</b></div>`).join(''):'<div class="empty">ไม่มีรายรับในเดือนนี้</div>'}
function summaryExpenseRows(a){return a.length?a.map(x=>`<div class="statline"><span>${thDate(x.date)} • ${esc(x.desc)} <small class="muted">${esc(x.category||'')}</small></span><b class="expense-number">−${money(Math.abs(n(x.amount)))}</b></div>`).join(''):'<div class="empty">ไม่มีรายจ่ายในเดือนนี้</div>'}
function roundedRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function canvasText(ctx,text,x,y,size=28,weight=500,color='#241b32',align='left'){ctx.font=`${weight} ${size}px system-ui,-apple-system,"Segoe UI",Tahoma,sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='alphabetic';ctx.fillText(String(text),x,y)}
function canvasMoney(v){return '฿'+n(v).toLocaleString('th-TH',{maximumFractionDigits:0})}
async function saveMonthlySummaryJPG(m){const prev=prevMonth(m),e=byMonth(state.entries,m),pe=byMonth(state.entries,prev),h=sum(e,x=>x.heads),ph=sum(pe,x=>x.heads),a=sum(e,x=>x.amount),inc=byMonth(state.funds,m).slice().sort((x,y)=>x.date.localeCompare(y.date)),exp=byMonth(state.expenses,m).slice().sort((x,y)=>x.date.localeCompare(y.date)),incTotal=sum(inc,x=>x.amount),expTotal=sum(exp,x=>x.amount),bal=centralBalance(m),pct=ph?((h-ph)/ph*100):0,staff=staffNames().map(s=>{const r=e.filter(x=>x.staff===s);return {name:s,amount:sum(r,x=>x.amount),heads:sum(r,x=>x.heads),days:window.BarberOps?BarberOps.workingDays(s,m):new Set(r.map(x=>x.date).filter(Boolean)).size}});const portraits=await Promise.all(staff.map(s=>window.BarberStaff?.load(s.name)||null));await document.fonts.ready;const W=1400,pad=72,rowH=48,staffRows=Math.max(1,Math.ceil(staff.length/3)),staffH=staffRows*270,ledgerRows=Math.max(inc.length,exp.length,1),ledgerH=120+ledgerRows*rowH,H=740+staffH+ledgerH+(window.WorkDetails?WorkDetails.jpgHeight(e):0),canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;const c=canvas.getContext('2d');c.fillStyle='#f5f7fc';c.fillRect(0,0,W,H);const grad=c.createLinearGradient(0,0,W,320);grad.addColorStop(0,'#2455c7');grad.addColorStop(.5,'#2455c7');grad.addColorStop(1,'#2455c7');roundedRect(c,0,0,W,330,0,grad);roundedRect(c,pad,50,36,56,12,'#ffffff');c.save();c.beginPath();c.rect(pad,55,36,46);c.clip();c.strokeStyle='#d72e45';c.lineWidth=9;for(let k=0;k<3;k++){c.beginPath();c.moveTo(pad-8,70+k*21);c.lineTo(pad+44,45+k*21);c.stroke()}c.restore();canvasText(c,'Barber Manager System By SORA',pad+52,75,22,800,'#ffffff');canvasText(c,(state.shopName||'รายงานร้านตัดผม').slice(0,70),pad+52,110,25,650,'#ffffff');canvasText(c,`สรุปรายเดือน • ${monthLabel(m)}`,pad,155,48,850,'#ffffff');canvasText(c,`รายงานสำหรับสมาชิก • เปรียบเทียบกับ ${monthLabel(prev)}`,pad,205,23,500,'rgba(255,255,255,.82)');const pctText=ph?`${pct>0?'↑':pct<0?'↓':'→'} ${Math.abs(pct).toFixed(1)}% ${pct>0?'เพิ่มขึ้น':pct<0?'ลดลง':'เท่าเดิม'}`:'— ไม่มีข้อมูลเดือนก่อน';canvasText(c,`${num(h)} คน`,pad,280,38,850,'#ffffff');canvasText(c,pctText,pad+300,280,25,800,pct>0?'#ffffff':pct<0?'#ffd2dd':'#ffffff');const cards=[['ยอดเงินรวมทั้งหมด',canvasMoney(a),''],['รายรับ / รายจ่าย',`${canvasMoney(incTotal)} / ${canvasMoney(expTotal)}`,''],['กองกลางคงเหลือ',canvasMoney(bal),'']];let cx=pad,cy=370,cw=(W-pad*2-28*2)/3;cards.forEach(([l,v])=>{roundedRect(c,cx,cy,cw,128,24,'#ffffff','#d6e0ef');canvasText(c,l,cx+22,cy+38,18,650,'#566b87');canvasText(c,v,cx+22,cy+88,31,850,'#182b49');cx+=cw+28});let y=540;canvasText(c,'สรุปช่างรายบุคคล',pad,y,32,850,'#182b49');y+=35;const cols=Math.min(3,Math.max(1,staff.length)),gap=22,sw=(W-pad*2-gap*(cols-1))/cols;staff.forEach((s,i)=>{const col=i%cols,row=Math.floor(i/cols),x=pad+col*(sw+gap),yy=y+row*270;roundedRect(c,x,yy,sw,242,22,'#ffffff','#d6e0ef');const avatarColors=[['#2455c7','#2455c7'],['#cc2941','#cc2941'],['#182b49','#182b49'],['#456fab','#456fab'],['#983447','#456fab'],['#456fab','#456fab'],['#182b49','#182b49'],['#cc2941','#2455c7']],ac=avatarColors[i%avatarColors.length],g=c.createLinearGradient(x,yy,x+52,yy+52);g.addColorStop(0,ac[0]);g.addColorStop(1,ac[1]);roundedRect(c,x+22,yy+20,50,50,15,g);if(portraits[i]){c.save();c.beginPath();c.arc(x+47,yy+45,25,0,Math.PI*2);c.clip();c.drawImage(portraits[i],x+22,yy+20,50,50);c.restore()}else{canvasText(c,STAFF_AVATARS[i%STAFF_AVATARS.length],x+47,yy+55,26,850,'#fff','center')};c.save();c.beginPath();c.rect(x+84,yy+20,sw-100,48);c.clip();canvasText(c,s.name,x+88,yy+52,25,800,'#182b49');c.restore();canvasText(c,`ลูกค้า  ${num(s.heads)} คน`,x+22,yy+105,20,650,'#566b87');canvasText(c,`ยอดเงิน  ${canvasMoney(s.amount)}`,x+22,yy+140,22,800,'#182b49');canvasText(c,`จำนวนเฉลี่ย/วัน  ${s.days?(s.heads/s.days).toFixed(2)+' คน/วัน':'—'}`,x+22,yy+177,18,650,'#566b87');canvasText(c,`วันทำงาน  ${num(s.days)} วัน`,x+22,yy+212,20,650,'#566b87')});y+=Math.ceil(staff.length/cols)*270+30;canvasText(c,'รายละเอียดรายรับ–รายจ่าย',pad,y,32,850,'#182b49');y+=34;const half=(W-pad*2-gap)/2;const drawLedger=(x,title,total,rows,isIncome)=>{const hh=90+Math.max(rows.length,1)*rowH;roundedRect(c,x,y,half,hh,22,'#ffffff','#d6e0ef');canvasText(c,title,x+22,y+38,24,800,isIncome?'#2455c7':'#cc2941');canvasText(c,canvasMoney(total),x+half-22,y+38,24,850,isIncome?'#2455c7':'#cc2941','right');if(!rows.length){canvasText(c,'ไม่มีรายการในเดือนนี้',x+22,y+85,18,500,'#566b87');return}rows.forEach((r,i)=>{const yy=y+82+i*rowH;canvasText(c,`${r.date.slice(8)}/${r.date.slice(5,7)}  ${r.desc}`,x+22,yy,17,550,'#182b49');canvasText(c,`${isIncome?'+':'−'}${canvasMoney(Math.abs(n(r.amount)))}`,x+half-22,yy,18,750,isIncome?'#2455c7':'#cc2941','right')})};drawLedger(pad,'รายรับ',incTotal,inc,true);drawLedger(pad+half+gap,'รายจ่าย',expTotal,exp,false);if(window.WorkDetails)WorkDetails.drawJPG(c,e,740+staffH+ledgerH-65);const footY=H-65;canvasText(c,`สร้างจาก Barber Manager • ${new Date().toLocaleString('th-TH')}`,pad,footY,16,500,'#566b87');const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.94));if(!blob){alert('ไม่สามารถสร้างไฟล์ JPG ได้');return}const name=`barber_summary_${m}.jpg`;if('showSaveFilePicker' in window){try{const handle=await window.showSaveFilePicker({id:'barber-summary-jpg',suggestedName:name,types:[{description:'JPEG Image',accept:{'image/jpeg':['.jpg','.jpeg']}}]});const writable=await handle.createWritable();await writable.write(blob);await writable.close();toast('บันทึกภาพสรุปรายเดือนแล้ว');return}catch(err){if(err?.name==='AbortError'){toast('ยกเลิกการบันทึกภาพ');return}}}const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('บันทึกภาพ JPG แล้ว')}

function entryPage(){const d=filters.entryDate||isoToday();return `<div class="card"><div class="section-title"><h2>บันทึกงานช่าง</h2><button class="btn alt-sage" data-csp-click="entry">＋ เพิ่มรายการ</button></div><div class="toolbar"><div class="field"><label>วันที่</label><input id="entryDate" type="date" value="${d}" data-csp-change="filter" data-csp-arg="entryDate"></div><div style="align-self:end" class="muted">${weekday(d)}</div></div>${entryTable(byDate(state.entries,d))}</div>`}
function entryTable(arr){if(!arr.length)return '<div class="empty">ยังไม่มีรายการในวันที่เลือก</div>';return `<div class="tablewrap"><table><thead><tr><th>ช่าง</th><th class="num">รายได้</th><th class="num">ลูกค้า</th><th class="num">เฉลี่ย/คน</th><th>หมายเหตุ</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td><b>${esc(x.staff)}</b></td><td class="num">${money(x.amount)}</td><td class="num">${num(x.heads)}</td><td class="num">${x.heads?money(x.amount/x.heads):'—'}</td><td>${esc(x.notes||'')}</td><td><div class="actions"><button class="btn small" data-csp-click="entry" data-csp-arg="${esc(x.id)}">แก้ไข</button><button class="btn small danger" data-csp-click="delete-entry" data-csp-arg="${esc(x.id)}">ลบ</button></div></td></tr>`).join('')}</tbody></table></div><div class="split" style="margin-top:12px"><b>รวม ${num(sum(arr,x=>x.heads))} คน</b><b class="bigmoney" style="font-size:24px">${money(sum(arr,x=>x.amount))}</b></div>`}
function openEntryModal(i=''){const x=state.entries.find(x=>x.id===i)||{id:'',date:filters.entryDate||isoToday(),staff:staffNames()[0]||'',amount:'',heads:'',notes:''};modal(`<div class="modalhead"><h3>${i?'แก้ไข':'เพิ่ม'}รายการงาน</h3><button class="close" data-csp-click="close-modal">✕</button></div><form data-csp-submit="entry" data-csp-arg="${esc(i)}"><div class="formgrid"><div class="field"><label>วันที่</label><input name="date" type="date" required value="${x.date}"></div><div class="field"><label>ช่าง</label><select name="staff" required>${staffNames().map(s=>`<option ${s===x.staff?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>รายได้ (บาท)</label><input name="amount" type="number" min="0" step="1" required value="${x.amount}"></div><div class="field"><label>จำนวนลูกค้า</label><input name="heads" type="number" min="0" step="1" required value="${x.heads}"></div><div class="field span4"><label>หมายเหตุ</label><textarea name="notes" placeholder="เช่น ฟรี 1 / ลูกค้าประจำ">${esc(x.notes||'')}</textarea></div><div class="span4 actions"><button class="btn alt-sage">บันทึก</button><button type="button" class="btn" data-csp-click="close-modal">ยกเลิก</button></div></div></form>`)}
function saveEntry(e,i){e.preventDefault();const f=new FormData(e.target),o={id:i||id(),date:f.get('date'),weekday:weekday(f.get('date')),staff:f.get('staff'),amount:n(f.get('amount')),heads:n(f.get('heads')),notes:String(f.get('notes')||'')};if(i){state.entries[state.entries.findIndex(x=>x.id===i)]=o}else state.entries.push(o);filters.entryDate=o.date;closeModal();save('บันทึกงานแล้ว')}
function dailyPage(){const d=filters.daily||isoToday(),e=byDate(state.entries,d),x=byDate(state.expenses,d),a=sum(e,z=>z.amount),h=sum(e,z=>z.heads),ex=sum(x,z=>z.amount);return `<div class="toolbar"><div class="field"><label>เลือกวันที่</label><input id="dailyDate" type="date" value="${d}"></div></div><div class="grid kpis">${kpi('รายได้',money(a),`${num(e.length)} รายการ`)}${kpi('ลูกค้า',num(h)+' คน',h?`เฉลี่ย ${money(a/h)}/คน`:'—')}${kpi('รายจ่าย',money(ex),`${num(x.length)} รายการ`)}${kpi('ผลต่างงานช่าง−รายจ่าย',money(a-ex),'รายได้งานช่าง − รายจ่ายร้าน')}</div><br><div class="grid two"><div class="card"><div class="section-title"><h2>${weekday(d)} ${thDate(d,true)}</h2></div>${entryTable(e)}</div><div class="card"><div class="section-title"><h2>รายจ่ายวันนี้</h2></div>${expenseMini(x)}</div></div>`}
function monthOptions(selected){const ms=new Set([...state.entries.map(x=>x.date.slice(0,7)),...state.funds.map(x=>x.date.slice(0,7)),...state.expenses.map(x=>x.date.slice(0,7)),...Object.keys(state.monthlySettings),currentMonth()]);return [...ms].sort().reverse().map(m=>`<option value="${m}" ${m===selected?'selected':''}>${monthLabel(m)}</option>`).join('')}
function monthlyPage(){const m=filters.month||currentMonth(),e=byMonth(state.entries,m),x=byMonth(state.expenses,m),a=sum(e,z=>z.amount),h=sum(e,z=>z.heads),ex=sum(x,z=>z.amount);const days=[...new Set(e.map(z=>z.date))].length;return `<div class="toolbar"><div class="field"><label>เดือน</label><select id="monthPick">${monthOptions(m)}</select></div><button class="btn" data-csp-click="month-csv" data-csp-arg="${esc(m)}">⬇ Export CSV</button></div><div class="grid kpis">${kpi('รายได้รวม',money(a),monthLabel(m))}${kpi('ลูกค้ารวม',num(h)+' คน',h?`เฉลี่ย ${money(a/h)}/คน`:'—')}${kpi('รายจ่าย',money(ex),`${x.length} รายการ`)}${kpi('ผลต่างงานช่าง−รายจ่าย',money(a-ex),'ก่อนค่าแรง/คอมมิชชัน')}${kpi('วันมีรายการ',num(days)+' วัน',days?`เฉลี่ย ${money(a/days)}/วัน`:'—')}</div><br><div class="grid two"><div class="card"><div class="section-title"><h2>ผลงานช่าง</h2></div>${staffPerformance(m)}</div><div class="card"><div class="section-title"><h2>สรุปรายจ่าย</h2></div>${expenseCategorySummary(m)}</div></div><br><div class="card"><div class="section-title"><h2>รายการรายวัน</h2><button class="btn ghost detail-toggle-btn" data-csp-click="monthly-details"><span class="toggle-arrow">▼</span>แสดงรายการ</button></div><div id="monthlyDailyDetails" hidden>${monthlyDaysTable(m)}</div></div>`}
function monthlyDaysTable(m){const map={};byMonth(state.entries,m).forEach(x=>{map[x.date]??={a:0,h:0};map[x.date].a+=n(x.amount);map[x.date].h+=n(x.heads)});const arr=Object.entries(map).sort((a,b)=>b[0].localeCompare(a[0]));if(!arr.length)return '<div class="empty">ไม่มีข้อมูล</div>';return `<div class="tablewrap"><table><thead><tr><th>วันที่</th><th>วัน</th><th class="num">รายได้</th><th class="num">ลูกค้า</th><th class="num">เฉลี่ย/คน</th></tr></thead><tbody>${arr.map(([d,v])=>`<tr><td>${thDate(d)}</td><td>${weekday(d)}</td><td class="num"><b>${money(v.a)}</b></td><td class="num">${num(v.h)}</td><td class="num">${v.h?money(v.a/v.h):'—'}</td></tr>`).join('')}</tbody></table></div>`}
function expenseCategorySummary(m){const map={};byMonth(state.expenses,m).forEach(x=>map[x.category||'ยังไม่จัดหมวด']=(map[x.category||'ยังไม่จัดหมวด']||0)+n(x.amount));const arr=Object.entries(map).sort((a,b)=>b[1]-a[1]),tot=sum(arr,x=>x[1]);return arr.length?arr.map(([k,v])=>`<div class="statline"><span>${esc(k)} <small class="muted">${tot?Math.round(v/tot*100):0}%</small></span><b class="expense-number">${money(v)}</b></div>`).join(''):'<div class="empty">ไม่มีรายจ่าย</div>'}
function goalsPage(){const m=filters.goalMonth||currentMonth(),s=state.monthlySettings[m]||{},g=s.goals||{total:{amount:0,heads:0},staff:{}},e=byMonth(state.entries,m),a=sum(e,x=>x.amount),h=sum(e,x=>x.heads);return `<div class="toolbar"><div class="field"><label>เดือน</label><select id="goalMonth">${monthOptions(m)}</select></div></div><div class="card"><div class="section-title"><h2>ตั้งเป้าหมาย • ${monthLabel(m)}</h2></div><form data-csp-submit="goals" data-csp-arg="${esc(m)}"><div class="formgrid"><div class="field"><label>เป้ารายได้รวม</label><input name="totalAmount" type="number" value="${n(g.total?.amount)}"></div><div class="field"><label>เป้าลูกค้ารวม</label><input name="totalHeads" type="number" value="${n(g.total?.heads)}"></div><div></div><div></div>${staffNames().map((st,i)=>`<div class="field"><label>${esc(st)} • เป้ารายได้</label><input name="sa${i}" type="number" value="${n(g.staff?.[st]?.amount)}"></div><div class="field"><label>${esc(st)} • เป้าลูกค้า</label><input name="sh${i}" type="number" value="${n(g.staff?.[st]?.heads)}"></div>`).join('')}<div class="span4 actions"><button class="btn primary">บันทึกเป้าหมาย</button></div></div></form></div><br><div class="card"><div class="section-title"><h2>ความคืบหน้า</h2></div>${goalProgressBlock(m,a,h,g)}</div>`}
function goalProgressBlock(m,a,h,g){const pct=(v,t)=>n(t)>0?Math.max(0,Math.min(100,n(v)/n(t)*100)):0,fmtPct=v=>(Math.round(v*10)/10).toLocaleString('th-TH',{maximumFractionDigits:1})+'%';const block=(name,aa,hh,gg,store=false)=>{const pa=pct(aa,gg?.amount),ph=pct(hh,gg?.heads);return `<div class="goal-progress-card ${store?'goal-store':''}"><div class="goal-progress-head"><div class="name">${store?'🏪 ':''}${esc(name)}</div><div class="muted">${money(aa)} • ${num(hh)} คน</div></div><div class="goal-progress-metrics"><div class="goal-metric"><div class="goal-metric-top"><span><b>รายได้</b> <span class="value">${money(aa)} / ${money(gg?.amount)}</span></span><span class="goal-percent money">${n(gg?.amount)>0?fmtPct(pa):'—'}</span></div><div class="goal-bar money"><i style="width:${pa}%"></i></div></div><div class="goal-metric"><div class="goal-metric-top"><span><b>จำนวนลูกค้า</b> <span class="value">${num(hh)} / ${num(gg?.heads)} คน</span></span><span class="goal-percent heads">${n(gg?.heads)>0?fmtPct(ph):'—'}</span></div><div class="goal-bar heads"><i style="width:${ph}%"></i></div></div></div></div>`};const rows=staffNames().map(st=>{const x=byMonth(state.entries,m).filter(e=>e.staff===st),aa=sum(x,z=>z.amount),hh=sum(x,z=>z.heads),gg=g.staff?.[st]||{};return block(st,aa,hh,gg,false)}).join('');return block('รวมร้าน',a,h,g.total||{},true)+rows}
function saveGoals(e,m){e.preventDefault();const f=new FormData(e.target),staff={};staffNames().forEach((s,i)=>staff[s]={amount:n(f.get('sa'+i)),heads:n(f.get('sh'+i))});state.monthlySettings[m]={...(state.monthlySettings[m]||{}),goals:{total:{amount:n(f.get('totalAmount')),heads:n(f.get('totalHeads'))},staff}};save('บันทึกเป้าหมายแล้ว')}
function toggleAnnualDetail(id,btn,label='รายละเอียด'){const box=document.getElementById(id);if(!box)return;const willShow=box.hasAttribute('hidden');if(willShow)box.removeAttribute('hidden');else box.setAttribute('hidden','');if(btn){btn.classList.toggle('is-open',willShow);btn.innerHTML=`<span class="toggle-arrow">▼</span>${willShow?'ซ่อน':'แสดง'}${label}`}}
function expensesPage(){const m=filters.expMonth||currentMonth(),arr=byMonth(state.expenses,m).slice().sort((a,b)=>b.date.localeCompare(a.date)),y=String(filters.expYear||isoToday().slice(0,4)),yearArr=byYear(state.expenses,y).slice().sort((a,b)=>b.date.localeCompare(a.date)),yearTotal=sum(yearArr,x=>x.amount);return `<div class="card"><div class="section-title"><h2>รายจ่ายร้าน</h2><button class="btn primary" data-csp-click="expense">＋ เพิ่มรายจ่าย</button></div><div class="toolbar"><div class="field"><label>เดือน</label><select data-csp-change="filter" data-csp-arg="expMonth">${monthOptions(m)}</select></div><b class="expense-number">รวม ${money(sum(arr,x=>x.amount))}</b></div>${expenseTable(arr)}</div><br><div class="card"><div class="section-title"><h2>สรุปรายจ่ายรวมทั้งปี</h2><span class="muted">เรียกดูข้อมูลย้อนหลังตามปี</span></div><div class="toolbar"><div class="field"><label>ปีรายจ่าย</label><select data-csp-change="filter" data-csp-arg="expYear">${yearOptions(y)}</select></div><span class="pill">📆 ปี ${Number(y)+543}</span></div><div class="grid kpis"><div class="kpi"><div class="label">รายจ่ายรวมทั้งปี</div><div class="num expense-number">${money(yearTotal)}</div><div class="sub">ปี ${Number(y)+543}</div></div><div class="kpi"><div class="label">จำนวนรายการทั้งปี</div><div class="num">${num(yearArr.length)} รายการ</div><div class="sub">กดปุ่มด้านล่างเพื่อดูรายละเอียด</div></div></div><div class="annual-detail-toggle"><button class="btn ghost detail-toggle-btn" data-csp-click="annual-expense-details"><span class="toggle-arrow">▼</span>แสดงรายละเอียด</button></div><div id="annualExpenseDetails" class="annual-detail-wrap" hidden><div class="section-title"><h3>รายละเอียดรายจ่ายทั้งปี</h3><b class="expense-number">รวม ${money(yearTotal)}</b></div>${expenseTable(yearArr,'ไม่มีรายจ่ายในปีที่เลือก')}</div></div>`}
function expenseTable(a,emptyText='ไม่มีรายจ่ายในเดือนนี้'){if(!a.length)return `<div class="empty">${emptyText}</div>`;return `<div class="tablewrap"><table><thead><tr><th>วันที่</th><th>รายการ</th><th>หมวด</th><th class="num">จำนวน</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td>${thDate(x.date)}</td><td>${esc(x.desc)}</td><td><span class="pill">${esc(x.category||'ยังไม่จัดหมวด')}</span></td><td class="num expense-number"><b>${money(x.amount)}</b></td><td><div class="actions"><button class="btn small" data-csp-click="expense" data-csp-arg="${esc(x.id)}">แก้ไข</button><button class="btn small danger" data-csp-click="delete-expense" data-csp-arg="${esc(x.id)}">ลบ</button></div></td></tr>`).join('')}</tbody></table></div>`}
function openExpenseModal(i=''){const x=state.expenses.find(x=>x.id===i)||{date:isoToday(),desc:'',amount:'',category:state.expenseCategories[0]};modal(`<div class="modalhead"><h3>${i?'แก้ไข':'เพิ่ม'}รายจ่าย</h3><button class="close" data-csp-click="close-modal">✕</button></div><form data-csp-submit="expense" data-csp-arg="${esc(i)}"><div class="formgrid"><div class="field"><label>วันที่</label><input name="date" type="date" required value="${x.date}"></div><div class="field span2"><label>รายการ</label><input name="desc" required value="${esc(x.desc)}"></div><div class="field"><label>จำนวนเงิน</label><input name="amount" type="number" min="0" required value="${x.amount}"></div><div class="field span2"><label>หมวด</label><select name="category">${[...new Set(['ยังไม่จัดหมวด',...state.expenseCategories])].map(c=>`<option ${c===(x.category||'ยังไม่จัดหมวด')?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="span4 actions"><button class="btn alt-sage">บันทึก</button><button type="button" class="btn" data-csp-click="close-modal">ยกเลิก</button></div></div></form>`)}
function saveExpense(e,i){e.preventDefault();const f=new FormData(e.target),o={id:i||id(),date:f.get('date'),desc:String(f.get('desc')),amount:n(f.get('amount')),category:String(f.get('category'))};if(i)state.expenses[state.expenses.findIndex(x=>x.id===i)]=o;else state.expenses.push(o);closeModal();save('บันทึกรายจ่ายแล้ว')}
function incomePage(){const m=filters.incomeMonth||currentMonth(),a=byMonth(state.funds,m).slice().sort((a,b)=>b.date.localeCompare(a.date)),y=String(filters.incomeYear||isoToday().slice(0,4)),yearArr=byYear(state.funds,y).slice().sort((a,b)=>b.date.localeCompare(a.date)),yearTotal=sum(yearArr,x=>x.amount);return `<div class="card"><div class="section-title"><h2>รายรับ</h2><button class="btn primary" data-csp-click="income">＋ เพิ่มรายรับ</button></div><div class="toolbar"><div class="field"><label>เดือน</label><select data-csp-change="filter" data-csp-arg="incomeMonth">${monthOptions(m)}</select></div><b>รวม ${money(sum(a,x=>x.amount))}</b></div><div class="notice">รายการกองกลางเดิมถูกนำมาใช้เป็น “รายรับ” เพื่อให้ข้อมูลเก่ายังคงต่อเนื่องกับสูตรกองกลางคงเหลือ</div>${incomeTable(a)}</div><br><div class="card"><div class="section-title"><h2>สรุปรายรับรวมทั้งปี</h2><span class="muted">เรียกดูข้อมูลย้อนหลังตามปี</span></div><div class="toolbar"><div class="field"><label>ปีรายรับ</label><select data-csp-change="filter" data-csp-arg="incomeYear">${yearOptions(y)}</select></div><span class="pill">📆 ปี ${Number(y)+543}</span></div><div class="grid kpis"><div class="kpi"><div class="label">รายรับรวมทั้งปี</div><div class="num good">${money(yearTotal)}</div><div class="sub">ปี ${Number(y)+543}</div></div><div class="kpi"><div class="label">จำนวนรายการทั้งปี</div><div class="num">${num(yearArr.length)} รายการ</div><div class="sub">กดปุ่มด้านล่างเพื่อดูรายละเอียด</div></div></div><div class="annual-detail-toggle"><button class="btn ghost detail-toggle-btn" data-csp-click="annual-income-details"><span class="toggle-arrow">▼</span>แสดงรายละเอียด</button></div><div id="annualIncomeDetails" class="annual-detail-wrap" hidden><div class="section-title"><h3>รายละเอียดรายรับทั้งปี</h3><b class="good">รวม ${money(yearTotal)}</b></div>${incomeTable(yearArr,'ไม่มีรายรับในปีที่เลือก')}</div></div>`}
function incomeTable(a,emptyText='ไม่มีรายรับในเดือนนี้'){if(!a.length)return `<div class="empty">${emptyText}</div>`;return `<div class="tablewrap"><table><thead><tr><th>วันที่</th><th>รายการ</th><th class="num">จำนวน</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td>${thDate(x.date)}</td><td>${esc(x.desc)}</td><td class="num good"><b>＋${money(Math.abs(n(x.amount)))}</b></td><td><div class="actions"><button class="btn small" data-csp-click="income" data-csp-arg="${esc(x.id)}">แก้ไข</button><button class="btn small danger" data-csp-click="delete-income" data-csp-arg="${esc(x.id)}">ลบ</button></div></td></tr>`).join('')}</tbody></table></div>`}
function openIncomeModal(i=''){const x=state.funds.find(x=>x.id===i)||{date:isoToday(),desc:'',amount:''};modal(`<div class="modalhead"><h3>${i?'แก้ไข':'เพิ่ม'}รายรับ</h3><button class="close" data-csp-click="close-modal">✕</button></div><form data-csp-submit="income" data-csp-arg="${esc(i)}"><div class="formgrid"><div class="field"><label>วันที่</label><input name="date" type="date" required value="${x.date}"></div><div class="field span2"><label>รายการ</label><input name="desc" required value="${esc(x.desc)}" placeholder="เช่น เพิ่มกองกลาง / ค่าสี"></div><div class="field"><label>จำนวนเงิน</label><input name="amount" type="number" min="0" step="1" required value="${Math.abs(n(x.amount))||''}"></div><div class="span4 actions"><button class="btn alt-sage">บันทึก</button><button type="button" class="btn" data-csp-click="close-modal">ยกเลิก</button></div></div></form>`)}
function saveIncome(e,i){e.preventDefault();const f=new FormData(e.target),o={id:i||id(),date:f.get('date'),desc:String(f.get('desc')),amount:Math.abs(n(f.get('amount')))};if(i)state.funds[state.funds.findIndex(x=>x.id===i)]=o;else state.funds.push(o);closeModal();save('บันทึกรายรับแล้ว')}
function expenseMini(a){return a.length?a.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="statline"><span>${esc(x.desc)} <small class="muted">${thDate(x.date)}</small></span><b class="expense-number">−${money(Math.abs(n(x.amount)))}</b></div>`).join(''):'<div class="empty">ไม่มีรายจ่าย</div>'}
function fundsPage(){const m=filters.fundMonth||currentMonth(),open=openingBalance(m),inc=receiptSum(m),ex=expenseSum(m),bal=centralBalance(m);return `<div class="toolbar"><div class="field"><label>เดือน</label><select data-csp-change="filter" data-csp-arg="fundMonth">${monthOptions(m)}</select></div></div><div class="card"><div class="section-title"><h2>กองกลางคงเหลือ • ${monthLabel(m)}</h2><button class="btn" data-csp-click="go" data-csp-arg="income">ดูรายรับ</button></div><div class="bigmoney balance-number">${money(bal)}</div><div class="muted">คำนวณอัตโนมัติตามสูตร: รายรับ − รายจ่าย + กองกลางคงเหลือเดือนก่อนหน้า</div><br><div class="formula-grid"><div class="formula-box"><div class="label">กองกลางคงเหลือเดือนก่อนหน้า</div><div class="value balance-number">${money(open)}</div></div><div class="formula-box"><div class="label">＋ รายรับเดือนนี้</div><div class="value good">${money(inc)}</div></div><div class="formula-box"><div class="label">− รายจ่ายเดือนนี้</div><div class="value expense-number">${money(ex)}</div></div><div class="formula-box"><div class="label">＝ กองกลางคงเหลือ</div><div class="value balance-number">${money(bal)}</div></div></div></div><br><div class="grid two"><div class="card"><div class="section-title"><h2>รายรับเดือนนี้</h2><span class="muted">${num(byMonth(state.funds,m).length)} รายการ</span></div>${incomeMini(byMonth(state.funds,m))}</div><div class="card"><div class="section-title"><h2>รายจ่ายเดือนนี้</h2><span class="muted">${num(byMonth(state.expenses,m).length)} รายการ</span></div>${expenseMini(byMonth(state.expenses,m))}</div></div><br><div class="card"><div class="section-title"><h2>รายการเคลื่อนไหวกองกลาง</h2></div>${centralLedger(m)}</div>`}
function incomeMini(a){return a.length?a.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="statline"><span>${esc(x.desc)} <small class="muted">${thDate(x.date)}</small></span><b class="good">＋${money(Math.abs(n(x.amount)))}</b></div>`).join(''):'<div class="empty">ไม่มีรายรับ</div>'}
function centralLedger(m){const rows=[...byMonth(state.funds,m).map(x=>({...x,type:'รายรับ',signed:Math.abs(n(x.amount))})),...byMonth(state.expenses,m).map(x=>({...x,type:'รายจ่าย',signed:-Math.abs(n(x.amount))}))].sort((a,b)=>b.date.localeCompare(a.date));if(!rows.length)return '<div class="empty">ไม่มีรายการในเดือนนี้</div>';return `<div class="tablewrap income-expense-ledger"><table><thead><tr><th>วันที่</th><th>ประเภท</th><th>รายการ</th><th class="num">จำนวน</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${thDate(x.date)}</td><td><span class="pill">${x.type}</span></td><td>${esc(x.desc)}</td><td class="num ${x.signed>=0?'good':'bad'}"><b>${x.signed>=0?'＋':'−'}${money(Math.abs(x.signed))}</b></td></tr>`).join('')}</tbody></table></div>`}
function fundTable(a){return incomeTable(a)}
function openFundModal(i=''){openIncomeModal(i)}
function saveFund(e,i){saveIncome(e,i)}
function analyticsPage(){const m=filters.anaMonth||currentMonth(),y=filters.anaYear||m.slice(0,4),e=byMonth(state.entries,m),a=sum(e,x=>x.amount),h=sum(e,x=>x.heads),prev=prevMonth(m),pe=byMonth(state.entries,prev),pa=sum(pe,x=>x.amount),ph=sum(pe,x=>x.heads);const change=(v,p)=>p?((v-p)/p*100):0;return `<div class="toolbar"><div class="field"><label>เดือนวิเคราะห์</label><select id="anaMonth">${monthOptions(m)}</select></div><div class="field"><label>ปีของกราฟเปรียบเทียบ</label><select id="anaYear">${yearOptions(y)}</select></div></div><div class="grid kpis">${kpi('รายได้งานช่าง',money(a),`${change(a,pa)>=0?'▲':'▼'} ${Math.abs(change(a,pa)).toFixed(1)}% จากเดือนก่อน`)}${kpi('ลูกค้า',num(h)+' คน',`${change(h,ph)>=0?'▲':'▼'} ${Math.abs(change(h,ph)).toFixed(1)}% จากเดือนก่อน`)}${kpi('เฉลี่ย/ลูกค้า',h?money(a/h):'—',monthLabel(m))}${kpi('เดือนก่อน',money(pa),monthLabel(prev))}</div><br><div class="grid two"><div class="card"><div class="section-title"><h2>วันเฉลี่ยที่มีลูกค้ามากที่สุด → น้อยที่สุด</h2></div>${weekdayAverageRanking(m)}</div><div class="card"><div class="section-title"><h2>ค่าเฉลี่ยจำนวนลูกค้าต่อวันของช่าง</h2></div>${staffWorkingDayAverage(m)}</div></div><br><div class="card"><div class="section-title"><h2>เปรียบเทียบจำนวนลูกค้าของช่างรายเดือน • ปี ${Number(y)+543}</h2><span class="muted">ม.ค. – ${chartMonthsForYear(y)===12?'ธ.ค.':monthShort(chartMonthsForYear(y))}</span></div>${customerLineChart(y)}</div><br><div class="grid two"><div class="card"><div class="section-title"><h2>สรุปวันในสัปดาห์</h2></div>${weekdayAnalytics(m)}</div><div class="card"><div class="section-title"><h2>อันดับช่างตามรายได้</h2></div>${staffRanking(m)}</div></div><br><div class="card"><div class="section-title"><h2>10 อันดับวันทำยอดสูงสุด</h2><span class="muted">แสดงสูงสุด 10 อันดับ</span></div>${topDays(m)}</div>`}
function prevMonth(m){let [y,mo]=m.split('-').map(Number);mo--;if(!mo){mo=12;y--}return `${y}-${String(mo).padStart(2,'0')}`}
function weekdayAverageRanking(m){const occ=weekdayOccurrenceCounts(m),em=byMonth(state.entries,m);const rows=WEEK.map(w=>{const total=sum(em.filter(x=>(x.weekday||weekday(x.date))===w),x=>x.heads),days=occ[w]||0;return {w,total,days,avg:days?total/days:0}}).filter(x=>x.days).sort((a,b)=>b.avg-a.avg||b.total-a.total);return rows.length?`<div>${rows.map((r,i)=>`<div class="avg-rank"><div class="badge">${i+1}</div><div><b>${r.w}</b><div class="muted">ลูกค้ารวม ${num(r.total)} คน ÷ ${num(r.days)} ${r.w}</div></div><b>${r.avg.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})} คน/วัน</b></div>`).join('')}</div><div class="notice" style="margin-top:12px">คำนวณแยกเฉพาะ ${monthLabel(m)} และนับจำนวนวันจริงของแต่ละวันในสัปดาห์; เดือนปัจจุบันจะไม่นับวันที่ยังมาไม่ถึง</div>`:'<div class="empty">ไม่มีข้อมูลสำหรับเดือนนี้</div>'}
function staffWorkingDayAverage(m){const rows=staffNames().map(s=>{const z=byMonth(state.entries,m).filter(x=>x.staff===s),h=sum(z,x=>x.heads),days=window.BarberOps?BarberOps.workingDays(s,m):new Set(z.map(x=>x.date).filter(Boolean)).size;return {s,h,days,avg:days?h/days:0}}).filter(x=>x.days>0).sort((a,b)=>b.avg-a.avg||b.h-a.h);return rows.length?rows.map((r,i)=>`<div class="avg-rank"><div class="badge">${i+1}</div><div><b>${esc(r.s)}</b><div class="muted">ลูกค้ารวม ${num(r.h)} คน ÷ วันทำงาน ${num(r.days)} วัน</div></div><b>${r.avg.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})} คน/วัน</b></div>`).join('')+'<div class="notice" style="margin-top:12px">สูตร: จำนวนลูกค้ารวมของช่างในเดือน ÷ จำนวนวันทำงานจริงของช่างในเดือนนั้น นับวันที่มีรายการงานหรือยืนยันมาทำงานแบบไม่ซ้ำกัน รวมวันมาทำงานที่ไม่มีลูกค้า</div>':'<div class="empty">ไม่มีข้อมูลวันทำงานของช่างในเดือนนี้</div>'}
function weekdayAnalytics(m){const occ=weekdayOccurrenceCounts(m),rows=WEEK.map(w=>{const z=byMonth(state.entries,m).filter(x=>(x.weekday||weekday(x.date))===w),a=sum(z,x=>x.amount),h=sum(z,x=>x.heads),d=occ[w]||0;return [w,a,h,d,d?h/d:0]}).filter(x=>x[3]);return `<div class="weekgrid">${rows.map(([w,a,h,d,av])=>`<div class="weekday"><span>${w}</span><b>${av.toLocaleString('th-TH',{minimumFractionDigits:1,maximumFractionDigits:1})} คน/วัน</b><small class="muted">รวม ${num(h)} คน • ${d} วัน<br>${money(a)}</small></div>`).join('')}</div>`}
function staffRanking(m){const r=staffNames().map(s=>{const z=byMonth(state.entries,m).filter(x=>x.staff===s);return [s,sum(z,x=>x.amount),sum(z,x=>x.heads)]}).sort((a,b)=>b[1]-a[1]);return r.map(([s,a,h],i)=>`<div class="rank"><div class="badge">${i+1}</div><div><b>${esc(s)}</b><div class="muted">${num(h)} คน • ${h?money(a/h)+'/คน':'—'}</div></div><b>${money(a)}</b></div>`).join('')}
function monthShort(m){return ['','ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'][Number(m)]||''}
function customerLineChart(y){const count=chartMonthsForYear(y);if(!count)return '<div class="empty">ไม่มีเดือนที่ผ่านมาสำหรับปีนี้</div>';const months=Array.from({length:count},(_,i)=>i+1),names=staffNames(),yearEntries=state.entries.filter(x=>x.date?.startsWith(`${y}-`));if(!yearEntries.length)return `<div class="empty">ยังไม่มีข้อมูลลูกค้าในปี ${Number(y)+543}</div>`;const data=names.map(s=>months.map(m=>sum(state.entries.filter(x=>x.staff===s&&x.date?.startsWith(`${y}-${String(m).padStart(2,'0')}`)),x=>x.heads))),max=Math.max(1,...data.flat()),W=980,H=410,L=60,R=28,T=42,B=54,pw=W-L-R,ph=H-T-B,steps=5,colors=['var(--chart-1)','var(--chart-2)','var(--chart-3)','var(--chart-4)','var(--chart-5)','var(--chart-6)'];const x=i=>L+(months.length===1?pw/2:i*pw/(months.length-1)),yy=v=>T+ph-(v/max*ph),grid=Array.from({length:steps+1},(_,i)=>{const v=max*i/steps,Y=yy(v);return `<line x1="${L}" y1="${Y}" x2="${W-R}" y2="${Y}" stroke="var(--line)" stroke-width="1"/><text x="${L-10}" y="${Y+4}" text-anchor="end" font-size="11" fill="var(--muted)">${Math.round(v)}</text>`}).join(''),labels=months.map((m,i)=>`<text x="${x(i)}" y="${H-18}" text-anchor="middle" font-size="11" fill="var(--muted)">${monthShort(m)}</text>`).join(''),offsets=[-11,17,-25,29,-39,41],lines=data.map((vals,si)=>{const c=colors[si%colors.length],pts=vals.map((v,i)=>`${x(i)},${yy(v)}`).join(' '),points=vals.map((v,i)=>{const px=x(i),py=yy(v),dy=offsets[si%offsets.length],labelY=Math.max(13,Math.min(H-B-5,py+dy));return `<circle cx="${px}" cy="${py}" r="4.5" fill="${c}"><title>${names[si]} • ${monthShort(months[i])} ${Number(y)+543}: ${num(v)} คน</title></circle><text class="point-value" x="${px}" y="${labelY}" text-anchor="middle" fill="${c}">${num(v)}</text>`}).join('');return `<polyline points="${pts}" fill="none" stroke="${c}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points}`}).join(''),legend=names.map((s,i)=>`<span class="legend-item"><i class="legend-dot" style="background:${colors[i%colors.length]}"></i>${esc(s)}</span>`).join('');return `<div class="chart-wrap"><svg class="linechart" viewBox="0 0 ${W} ${H}" role="img" aria-label="กราฟเปรียบเทียบจำนวนลูกค้าของช่างรายเดือน">${grid}<line x1="${L}" y1="${T}" x2="${L}" y2="${H-B}" stroke="var(--muted)"/><line x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}" stroke="var(--muted)"/>${labels}${lines}<text x="16" y="${T+ph/2}" transform="rotate(-90 16 ${T+ph/2})" text-anchor="middle" font-size="12" fill="var(--muted)">จำนวนลูกค้า (คน)</text></svg></div><div class="chart-legend">${legend}</div><div class="muted" style="font-size:12px;margin-top:8px">ตัวเลขบนแต่ละจุดคือจำนวนลูกค้ารวมของช่างรายนั้นในเดือนนั้น • เลือกปีจากด้านบนเพื่อดูย้อนหลัง</div>`}
function topDays(m){const map={};byMonth(state.entries,m).forEach(x=>{map[x.date]??={a:0,h:0};map[x.date].a+=n(x.amount);map[x.date].h+=n(x.heads)});const a=Object.entries(map).sort((a,b)=>b[1].a-a[1].a).slice(0,10);return a.length?`<div class="tablewrap"><table><thead><tr><th>อันดับ</th><th>วันที่</th><th>วัน</th><th class="num">รายได้ + จำนวนลูกค้า</th></tr></thead><tbody>${a.map(([d,v],i)=>`<tr><td>${i+1}</td><td>${thDate(d)}</td><td>${weekday(d)}</td><td class="num"><div style="display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap"><b>${money(v.a)}</b><span class="pill">👥 ${num(v.h)} คน</span></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">ไม่มีข้อมูล</div>'}
function historyPage(){const q=(filters.q||'').toLowerCase(),st=filters.histStaff||'',m=filters.histMonth||'';let a=state.entries.slice().sort((a,b)=>b.date.localeCompare(a.date));if(q)a=a.filter(x=>`${x.date} ${x.staff} ${x.notes||''}`.toLowerCase().includes(q));if(st)a=a.filter(x=>x.staff===st);if(m)a=a.filter(x=>x.date.startsWith(m));return `<div class="card"><div class="section-title"><h2>ประวัติงานทั้งหมด</h2><span class="muted">${num(a.length)} รายการ</span></div><div class="toolbar"><input placeholder="ค้นหา วันที่ / ช่าง / หมายเหตุ" value="${esc(filters.q||'')}" data-csp-input="filter" data-csp-arg="q"><select data-csp-change="filter" data-csp-arg="histStaff"><option value="">ช่างทั้งหมด</option>${staffNames().map(s=>`<option ${s===st?'selected':''}>${esc(s)}</option>`).join('')}</select><select data-csp-change="filter" data-csp-arg="histMonth"><option value="">ทุกเดือน</option>${monthOptions(m)}</select></div>${historyTable(a.slice(0,500))}${a.length>500?'<div class="notice" style="margin-top:12px">แสดง 500 รายการแรกตามตัวกรอง เพื่อให้โปรแกรมทำงานลื่น</div>':''}</div>`}
function historyTable(a){if(!a.length)return '<div class="empty">ไม่พบข้อมูล</div>';return `<div class="tablewrap"><table><thead><tr><th>วันที่</th><th>วัน</th><th>ช่าง</th><th class="num">รายได้</th><th class="num">ลูกค้า</th><th>หมายเหตุ</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td>${thDate(x.date)}</td><td>${weekday(x.date)}</td><td><b>${esc(x.staff)}</b></td><td class="num">${money(x.amount)}</td><td class="num">${num(x.heads)}</td><td>${esc(x.notes||'')}</td><td><button class="btn small" data-csp-click="entry" data-csp-arg="${esc(x.id)}">แก้ไข</button></td></tr>`).join('')}</tbody></table></div>`}
function staffPage(){const hasShop=!!String(state.shopName||'').trim();return `<div class="grid two"><div class="card"><div class="section-title"><h2>รายชื่อช่าง</h2><button class="btn primary" data-csp-click="add-staff">＋ เพิ่มช่าง</button></div>${state.staff.map((s,i)=>`<div class="staff-row"><b>${esc(s.name)}</b><div class="muted">${num(state.entries.filter(x=>x.staff===s.name).length)} รายการประวัติ</div><div class="actions"><button class="btn small" data-csp-click="rename-staff" data-csp-arg="${esc(i)}">เปลี่ยนชื่อ</button><button class="btn small danger" data-csp-click="remove-staff" data-csp-arg="${esc(i)}">ลบ</button></div></div>`).join('')}</div><div class="card shop-settings"><div class="section-title"><h2>จัดการร้าน</h2></div><div class="shop-name-card"><div class="muted">ชื่อร้านที่แสดงบนแถบด้านบน</div><div class="current-shop-name">${hasShop?esc(state.shopName):'ยังไม่ได้ตั้งชื่อร้าน'}</div><div class="actions"><button class="btn primary" data-csp-click="edit-shop-name">${hasShop?'✏️ แก้ไขชื่อร้าน':'＋ เพิ่มชื่อร้าน'}</button>${hasShop?'<button class="btn ghost" data-csp-click="clear-shop-name">ล้างชื่อร้าน</button>':''}</div></div><div><h3>การจัดการชื่อช่างและร้าน</h3><p class="muted">การเปลี่ยนชื่อช่างจะอัปเดตประวัติรายการงานและเป้าหมายรายเดือนให้ตรงกันทั้งหมด ส่วนการลบรายชื่อช่างจะไม่ลบประวัติเก่า ชื่อร้านจะถูกเก็บพร้อมข้อมูลโปรแกรมและรวมอยู่ใน Backup JSON</p></div></div></div>`}
function addStaff(){const name=prompt('ชื่อช่างใหม่');if(!name?.trim())return;if(staffNames().includes(name.trim()))return toast('มีชื่อนี้แล้ว');state.staff.push({name:name.trim()});save('เพิ่มช่างแล้ว')}
function renameStaff(i){const old=state.staff[i].name,nn=prompt('เปลี่ยนชื่อช่าง',old);if(!nn?.trim()||nn.trim()===old)return;if(staffNames().includes(nn.trim()))return toast('มีชื่อนี้แล้ว');state.staff[i].name=nn.trim();state.entries.forEach(x=>{if(x.staff===old)x.staff=nn.trim()});Object.values(state.monthlySettings).forEach(s=>{if(s.goals?.staff?.[old]){s.goals.staff[nn.trim()]=s.goals.staff[old];delete s.goals.staff[old]}});save('เปลี่ยนชื่อแล้ว')}
function removeStaff(i){const s=state.staff[i].name;if(!confirm(`ลบ ${s} ออกจากรายชื่อช่าง? ประวัติงานเดิมจะยังอยู่`))return;state.staff.splice(i,1);save('ลบรายชื่อแล้ว')}
function editShopName(){const current=String(state.shopName||'');const v=prompt(current?'แก้ไขชื่อร้าน':'เพิ่มชื่อร้าน',current);if(v===null)return;const name=String(v).trim();if(!name){alert('กรุณากรอกชื่อร้าน');return}state.shopName=name;save('บันทึกชื่อร้านแล้ว')}
function clearShopName(){if(!confirm('ล้างชื่อร้านที่แสดงอยู่หรือไม่?'))return;state.shopName='';save('ล้างชื่อร้านแล้ว')}
function backupPage(){const dup=duplicateCount();return `<div class="grid two"><div class="card"><div class="section-title"><h2>สำรอง / นำเข้าข้อมูล</h2></div><p class="muted">ข้อมูลใช้งานหลักเก็บในเบราว์เซอร์เครื่องนี้ และสามารถสร้าง Snapshot สำรองไว้ใน IndexedDB ได้ฟรี</p><div class="actions"><button class="btn primary" data-csp-click="snapshot">🗄️ สำรองลง IndexedDB</button><button class="btn" data-csp-click="restore-snapshot">↩️ กู้คืน Snapshot ล่าสุด</button><button class="btn" data-csp-click="backup">💾 Export JSON</button><label class="btn">⬆ นำเข้า JSON<input type="file" accept=".json,application/json" data-csp-change="import-json" hidden></label><button class="btn" data-csp-click="all-csv">📊 Export CSV</button></div><br><div class="notice"><b>IndexedDB Snapshot:</b> เก็บข้อมูลสำรองไว้ภายในเบราว์เซอร์/อุปกรณ์นี้ สูงสุด 20 ชุด และไม่ส่งข้อมูลร้านขึ้น GitHub</div><br><div class="notice"><b>สำคัญ:</b> IndexedDB ไม่ซิงก์ข้ามเครื่องอัตโนมัติ หากต้องการย้ายข้อมูลระหว่างมือถือกับคอมให้ใช้ Export JSON → Import JSON</div></div><div class="card"><div class="section-title"><h2>ตรวจสุขภาพข้อมูล</h2></div>${healthRow('รายการงาน',state.entries.length)}${healthRow('รายจ่าย',state.expenses.length)}${healthRow('รายรับ',state.funds.length)}${healthRow('รายการวันที่+ช่างซ้ำ',dup,dup?'warn':'good')}<div style="margin-top:14px" class="muted" id="idbBackupStatus">กำลังตรวจ IndexedDB…</div></div></div><br><div class="card dangerzone"><div class="section-title"><h2>รีเซ็ตโปรแกรม</h2></div><p class="muted">รีเซ็ตเป็นข้อมูลว่างสำหรับเว็บ ก่อนรีเซ็ตระบบจะสร้าง Snapshot ลง IndexedDB ให้อัตโนมัติ</p><button class="btn danger" data-csp-click="reset-shop">ล้างข้อมูลในเครื่องนี้</button></div><div class="footer">Barber Manager V1.10.8.1 Web • Base V1.10.7 • PWA + IndexedDB Snapshot</div>`}
function healthRow(l,v,c=''){return `<div class="statline"><span>${l}</span><b class="${c}">${num(v)}</b></div>`}
function duplicateCount(){const m=new Map;state.entries.forEach(x=>{const k=x.date+'|'+x.staff;m.set(k,(m.get(k)||0)+1)});return [...m.values()].filter(n=>n>1).length}
function del(k,i){if(!confirm('ยืนยันลบรายการนี้?'))return;state[k]=state[k].filter(x=>x.id!==i);save('ลบแล้ว')}
function modal(h){const box=document.getElementById('modalbox'),overlay=document.getElementById('modal');box.classList.remove("work-entry-modal");box.innerHTML=h;box.scrollTop=0;overlay.classList.add('open');document.body.classList.add('modal-open');requestAnimationFrame(()=>{overlay.scrollTop=0;box.scrollTop=0})} function closeModal(){document.getElementById('modal').classList.remove('open');document.body.classList.remove('modal-open')}
const IDB_DB='sora-sub-workspace-snapshots:'+(COMMERCIAL_PROFILE==='default'?'':':'+COMMERCIAL_PROFILE);
const IDB_STORE='snapshots';
const IDB_MAX=20;
function openBackupDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(IDB_DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(IDB_STORE))db.createObjectStore(IDB_STORE,{keyPath:'id',autoIncrement:true})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function createIDBSnapshot(showToast=false){try{const db=await openBackupDB();const tx=db.transaction(IDB_STORE,'readwrite'),store=tx.objectStore(IDB_STORE);store.add({createdAt:new Date().toISOString(),data:clone(state),version:'S0.18.0'});await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});const tx2=db.transaction(IDB_STORE,'readwrite'),s2=tx2.objectStore(IDB_STORE),all=await new Promise((res,rej)=>{const r=s2.getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)});if(all.length>IDB_MAX){all.sort((a,b)=>a.id-b.id).slice(0,all.length-IDB_MAX).forEach(x=>s2.delete(x.id))}await new Promise((res,rej)=>{tx2.oncomplete=res;tx2.onerror=()=>rej(tx2.error)});db.close();if(showToast)toast('สำรอง Snapshot ลง IndexedDB แล้ว');updateIDBBackupStatus();return true}catch(e){console.error(e);if(showToast)alert('ไม่สามารถสำรอง IndexedDB ได้ในเบราว์เซอร์นี้');return false}}
async function latestIDBSnapshot(){const db=await openBackupDB();const tx=db.transaction(IDB_STORE,'readonly'),store=tx.objectStore(IDB_STORE);const all=await new Promise((res,rej)=>{const r=store.getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)});db.close();return all.sort((a,b)=>b.id-a.id)[0]||null}
async function restoreLatestIDBSnapshot(){try{const snap=await latestIDBSnapshot();if(!snap){alert('ยังไม่มี Snapshot ใน IndexedDB');return}if(!confirm(`กู้คืน Snapshot วันที่ ${new Date(snap.createdAt).toLocaleString('th-TH')} และแทนที่ข้อมูลปัจจุบันหรือไม่?`))return;state=upgrade(clone(snap.data));WorkspaceStorage.setItem(STORAGE,JSON.stringify(state));await WorkspaceStorage.flush();await window.OwnerWorkspace.refresh();toast('กู้คืน Snapshot สำเร็จ');render()}catch(e){console.error(e);alert('กู้คืน Snapshot ไม่สำเร็จ')}}
async function updateIDBBackupStatus(){const el=document.getElementById('idbBackupStatus');if(!el)return;try{const db=await openBackupDB();const tx=db.transaction(IDB_STORE,'readonly'),store=tx.objectStore(IDB_STORE);const all=await new Promise((res,rej)=>{const r=store.getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)});db.close();if(!all.length){el.textContent='IndexedDB: ยังไม่มี Snapshot';return}all.sort((a,b)=>b.id-a.id);el.textContent=`IndexedDB: ${all.length} Snapshot • ล่าสุด ${new Date(all[0].createdAt).toLocaleString('th-TH')}`}catch(e){el.textContent='IndexedDB: ไม่พร้อมใช้งาน'}}
async function resetSeedWeb(){if(!confirm('ล้างข้อมูลทั้งหมดในเบราว์เซอร์เครื่องนี้จริงหรือไม่?'))return;await createIDBSnapshot(false);state=upgrade(clone(SEED));WorkspaceStorage.removeItem(STORAGE);save('ล้างข้อมูลในเครื่องนี้แล้ว')}
function download(name,text,type='application/json'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function saveBackupAs(){
 const out={...state,appMeta:{app:'Barber Manager V1.10.8.1 Web — Base V1.10.7',exportedAt:new Date().toISOString()}};
 const name=`barber_backup_${isoToday()}.json`;
 const text=JSON.stringify(out,null,2);
 if('showSaveFilePicker' in window){
  try{
   const handle=await window.showSaveFilePicker({
    id:'barber-manager-backup',
    suggestedName:name,
    types:[{description:'Barber Manager Backup (JSON)',accept:{'application/json':['.json']}}],
    excludeAcceptAllOption:false
   });
   const writable=await handle.createWritable();
   await writable.write(new Blob([text],{type:'application/json'}));
   await writable.close();
   toast('บันทึก Backup เรียบร้อยแล้ว');
   return;
  }catch(err){
   if(err && err.name==='AbortError'){toast('ยกเลิกการบันทึก Backup');return;}
   console.warn('Save picker unavailable, falling back to download:',err);
  }
 }
 download(name,text);
 toast('เบราว์เซอร์นี้ใช้หน้าต่างเลือกที่เก็บไม่ได้ จึงดาวน์โหลด Backup แบบปกติแทน');
}
function downloadBackup(){return saveBackupAs()}
function importJSON(file){if(!file)return;const r=new FileReader;r.onload=async()=>{try{const d=JSON.parse(r.result);if(!Array.isArray(d.entries)||!Array.isArray(d.staff))throw Error('รูปแบบไม่ตรง');if(confirm(`พบ ${d.entries.length} รายการงาน ต้องการแทนที่ข้อมูลปัจจุบันหรือไม่?`)){await createIDBSnapshot(false);state=upgrade(d);save('นำเข้าข้อมูลสำเร็จ')}}catch(e){alert('นำเข้าไม่ได้: ไฟล์ JSON ไม่ใช่รูปแบบข้อมูลร้านที่รองรับ')}};r.readAsText(file,'utf-8')}
function csvCell(v){v=String(v??'');return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')}
function exportAllCSV(){const rows=[['วันที่','วัน','ช่าง','รายได้','จำนวนลูกค้า','หมายเหตุ'],...state.entries.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[x.date,weekday(x.date),x.staff,x.amount,x.heads,x.notes||''])];download(`barber_entries_${isoToday()}.csv`,csv(rows),'text/csv;charset=utf-8');toast('Export CSV แล้ว')}
function exportMonthCSV(m){const rows=[['วันที่','วัน','ช่าง','รายได้','จำนวนลูกค้า','หมายเหตุ'],...byMonth(state.entries,m).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[x.date,weekday(x.date),x.staff,x.amount,x.heads,x.notes||''])];download(`barber_${m}.csv`,csv(rows),'text/csv;charset=utf-8')}
function resetSeed(){if(!confirm('คืนค่าข้อมูลต้นฉบับจริงหรือไม่?'))return;state=upgrade(clone(SEED));WorkspaceStorage.removeItem(STORAGE);save('คืนค่าข้อมูลต้นฉบับแล้ว')}

if('serviceWorker' in navigator)window.addEventListener('load',()=>Promise.resolve().catch(console.warn));
if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(()=>{});
loadTheme();
render();
